#!/usr/bin/env bash
set -eu; A1="$(cd "$(dirname "$0")" && pwd)"; A2="$A1/../.."; A3=install; while [ $# -gt 0 ]; do case "$1" in --uninstall) A3=uninstall ;; --gmod) shift; A2="$1" ;; *) echo "Unknown option: $1"; exit 2 ;; esac; shift; done; A2="$(cd "$A2" 2>/dev/null && pwd)" || { echo "ERROR: Garry's Mod folder not found. Use --gmod \"/path/to/garrysmod\"."; exit 1; }; A4="$A2/lua/menu/menu.lua"; [ -f "$A4" ] || { echo "ERROR: $A4 not found. Is '$A2' the 'garrysmod' folder? Use --gmod."; exit 1; }; [ "$A2" != "$A1" ] || { echo "ERROR: run this from the addons/LunarShade folder."; exit 1; }; A5='--[[ LUNAR SHADE MAIN MENU BEGIN (remove with Uninstall-MainMenu) ]]'; A6='--[[ LUNAR SHADE MAIN MENU END ]]'; A7='MsgC(Color(157,125,255), "[Lunar Shade] menu.lua line is running\n"); pcall(file.Delete, "lunar_shade_menu_status.txt"); pcall(file.Write, "lunar_shade_probe.txt", "menu.lua line ran"); local ok, e = pcall(include, "lunar_shade_menu/mn_boot.lua"); if not file.Exists("lunar_shade_menu_status.txt", "DATA") then pcall(file.Write, "lunar_shade_menu_status.txt", "error: boot file did not run (pcall=" .. tostring(ok) .. " " .. tostring(e) .. ")") end'; f1() { awk -v b="$A5" -v e="$A6" 'index($0,b){skip=1} !skip{print} index($0,e){skip=0}' "$1"; }; T1="$(mktemp)"; trap 'rm -f "$T1"' EXIT; if [ "$A3" = uninstall ]; then f1 "$A4" > "$T1"; cat "$T1" > "$A4"; rm -rf "$A2/lua/lunar_shade_menu"; rm -f "$A2/lua/lunar_shade/sh_presets.lua"; rm -f "$A2/lua/lunar_shade/sh_crypt.lua"; rm -f "$A2/data/lunar_shade_menu_status.txt"; echo "Lunar Shade main menu removed. Restart Garry's Mod."; exit 0; fi; [ -f "$A4.lunarshade.bak" ] || cp "$A4" "$A4.lunarshade.bak"; { printf '%s\n%s\n%s\n' "$A5" "$A7" "$A6"; f1 "$A4"; } > "$T1"; cat "$T1" > "$A4"; mkdir -p "$A2/lua/lunar_shade_menu" "$A2/lua/lunar_shade"; cp -f "$A1/lua/lunar_shade_menu/"*.lua "$A2/lua/lunar_shade_menu/"; cp -f "$A1/lua/lunar_shade/sh_presets.lua" "$A2/lua/lunar_shade/sh_presets.lua"; cp -f "$A1/lua/lunar_shade/sh_crypt.lua" "$A2/lua/lunar_shade/sh_crypt.lua"; echo "Lunar Shade main menu installed."; echo "  patched : $A4  (backup: menu.lua.lunarshade.bak)"; echo "  copied  : $A2/lua/lunar_shade_menu/ and lua/lunar_shade/sh_presets.lua"; echo "Restart Garry's Mod completely. Re-run this after updating Lunar Shade or after a Garry's Mod update."
